describe("doctests of sympy.simplify.epathtools", () => {
  // no value
  //   path.apply(expr, lambda expr: expr**2)
  //   => [((x**2, 1), 2), ((3, y**2), z)]
  it.todo("path.apply(expr, lambda expr: expr**2)");
  // no value
  //   path.apply(expr, lambda expr: 2*expr)
  //   => t + sin(2*x + 1) + cos(2*x + 2*y + E)
  it.todo("path.apply(expr, lambda expr: 2*expr)");
  // no value
  //   path.select(expr)
  //   => [x, y]
  it.todo("path.select(expr)");
  // no value
  //   path.select(expr)
  //   => [x, x, y]
  it.todo("path.select(expr) (2)");
  it("epath(path, expr)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr([x, y])).toBe('[x, y]');
  });
  // a primitive result that no library call returned
  //   epath(path, expr, lambda expr: expr**2)
  //   => [((x**2, 1), 2), ((3, y**2), z)]
  it.todo("epath(path, expr, lambda expr: expr**2)");
  it("epath(path, expr) (2)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr([x, x, y])).toBe('[x, x, y]');
  });
  // a callback parameter outside its callback
  //   epath(path, expr, lambda expr: 2*expr)
  //   => t + sin(2*x + 1) + cos(2*x + 2*y + E)
  it.todo("epath(path, expr, lambda expr: 2*expr)");
});

